payload.question:
$mmtThy = Import-Clixml -Path "$env:TEMP\mmtThy.xml"
$root = "c:\Users\zane\Desktop\Praktikum\UPL\test\latin2"
$folders = @('algebraic_logic','category_theory','computation','curry-howard','domain_theories','foundations','fundamentals','logic','set-theoretical_semantics','set_theory','type_theory','_orga')
$rows=@()
foreach ($f in $folders) {
  $path = Join-Path $root $f
  if (-not (Test-Path $path)) { continue }
  $complete=0; $total=0; $notInMmt=0
  foreach ($file in (Get-ChildItem -Path $path -Recurse -Filter *.p -File)) {
    $lines = [System.IO.File]::ReadAllLines($file.FullName, [System.Text.Encoding]::UTF8)
    for ($i=0; $i -lt $lines.Length; $i++) {
      $ln = $lines[$i]
      $mThyA = [regex]::Match($ln, '^\s*theory\s+([A-Za-z0-9_]+)\s*\{')
      $mThyC = [regex]::Match($ln, '^\s*//\s*theory\s+([A-Za-z0-9_]+)\s*\{')
      $mVwA  = [regex]::Match($ln, '^\s*([A-Za-z0-9_]+)\s*:\s*[^\r\n]*->[^\r\n]*=\s*[^\r\n]*->')
      $mVwC  = [regex]::Match($ln, '^\s*//\s*([A-Za-z0-9_]+)\s*:\s*[^\r\n]*->[^\r\n]*=\s*[^\r\n]*->')
      $kind=$null; $name=$null; $commented=$false
      if ($mThyA.Success) { $kind='thy'; $name=$mThyA.Groups[1].Value }
      elseif ($mThyC.Success) { $kind='thy'; $name=$mThyC.Groups[1].Value; $commented=$true }
      elseif ($mVwA.Success) { $kind='view'; $name=$mVwA.Groups[1].Value }
      elseif ($mVwC.Success) { $kind='view'; $name=$mVwC.Groups[1].Value; $commented=$true }
      else { continue }
      $total++
      # gather body
      $body=@()
      if ($commented) {
        for ($j=$i+1; $j -lt $lines.Length; $j++) {
          $l2=$lines[$j]; if ($l2.Trim() -eq '') { continue }
          if ($l2 -notmatch '^\s*//') { break }
          $c=($l2 -replace '^\s*//\s?','').Trim()
          if ($c -eq '}') { break }
          if ($c -match '^theory\s+[A-Za-z0-9_]+\s*\{') { break }
          if ($c -match '^[A-Za-z0-9_]+\s*:\s*.*->.*=\s*.*->') { break }
          $body += $c
        }
      } else {
        $depth=0; $started=$false
        for ($j=$i; $j -lt $lines.Length; $j++) {
          $l2=$lines[$j]
          $o=([regex]::Matches($l2,'\{')).Count; $cl=([regex]::Matches($l2,'\}')).Count
          if ($j -gt $i) { $body += $l2 }
          $depth += $o - $cl
          if ($o -gt 0) { $started=$true }
          if ($started -and $depth -le 0) { break }
        }
      }
      $hasDef=$false; $hasHole=$false
      foreach ($b in $body) {
        $t=$b.Trim()
        if ($t -eq '' -or $t -eq '{' -or $t -eq '}') { continue }
        if ($t -match '^//') { continue }
        if ($t -match '\?\?\?') { $hasHole=$true; continue }
        if ($t -match '\bTODO\b') { $hasHole=$true; continue }
        if ($t -match '^include\b') { continue }
        if ($t -match ':' -or $t -match '=' -or $t -match '^type\b' -or $t -match '^realize\b') { $hasDef=$true }
      }
      $isComplete=$false
      if ($kind -eq 'view') { $isComplete = ($hasDef -and (-not $hasHole)) }
      else {
        if ($hasDef -and (-not $hasHole)) { $isComplete=$true }
        elseif ((-not $hasDef) -and (-not $hasHole)) {
          if ($mmtThy.ContainsKey($name)) { $isComplete = (-not $mmtThy[$name]) } else { $notInMmt++; $isComplete=$false }
        }
      }
      if ($isComplete) { $complete++ }
    }
  }
  $rows += [pscustomobject]@{Folder=$f; Complete=$complete; Total=$total; NotInMMT=$notInMmt}
}
$rows | ForEach-Object { Write-Output ("{0}|{1}/{2}|notInMMT={3}" -f $_.Folder,$_.Complete,$_.Total,$_.NotInMMT) }
Write-Output ("TOTAL|{0}/{1}" -f (($rows | Measure-Object -Property Complete -Sum).Sum), (($rows | Measure-Object -Property Total -Sum).Sum))

