        for ($j=$i+1; $j -lt $lines.Length; $j++) {
          $l2=$lines[$j]; if ($l2.Trim() -eq '') { continue }
          if ($l2 -notmatch '^\s*//') { break }
          $c=($l2 -replace '^\s*//\s?','').Trim()
