          if ($mmtThy.ContainsKey($name)) { $isComplete = (-not $mmtThy[$name]) } else { $notInMmt++; $isComplete=$false }
        }
      }
      if ($isComplete) { $complete++ }
    }
  }
  $rows += [pscustomobject]@{Folder=$f; Complete=$complete; Total=$total; NotInMMT=$notInMmt}
}
