$cnt = Import-Clixml -Path "$env:TEMP\mmtCnt.xml"
$root = "c:\Users\zane\Desktop\Praktikum\UPL\test\latin2"
$folders = @('algebraic_logic','category_theory','computation','curry-howard','domain_theories','foundations','fundamentals','logic','set-theoretical_semantics','set_theory','type_theory','_orga')
$rows=@()
foreach ($f in $folders) {
  $path = Join-Path $root $f
  if (-not (Test-Path $path)) { continue }
  $comp=0;$part=0;$emp=0;$tot=0
  foreach ($file in (Get-ChildItem -Path $path -Recurse -Filter *.p -File)) {
    $lines = [System.IO.File]::ReadAllLines($file.FullName, [System.Text.Encoding]::UTF8)
    for ($i=0; $i -lt $lines.Length; $i++) {
      $ln=$lines[$i]
      $a=[regex]::Match($ln,'^\s*theory\s+([A-Za-z0-9_]+)\s*\{'); $b=[regex]::Match($ln,'^\s*//\s*theory\s+([A-Za-z0-9_]+)\s*\{')
      $c=[regex]::Match($ln,'^\s*([A-Za-z0-9_]+)\s*:\s*[^\r\n]*->[^\r\n]*=\s*[^\r\n]*->'); $d=[regex]::Match($ln,'^\s*//\s*([A-Za-z0-9_]+)\s*:\s*[^\r\n]*->[^\r\n]*=\s*[^\r\n]*->')
      $kind=$null;$name=$null;$cm=$false
      if($a.Success){$kind='thy';$name=$a.Groups[1].Value}elseif($b.Success){$kind='thy';$name=$b.Groups[1].Value;$cm=$true}elseif($c.Success){$kind='vw';$name=$c.Groups[1].Value}elseif($d.Success){$kind='vw';$name=$d.Groups[1].Value;$cm=$true}else{continue}
      $tot++
      $body=@()
      if($cm){ for($j=$i+1;$j -lt $lines.Length;$j++){ $l2=$lines[$j]; if($l2.Trim() -eq ''){continue}; if($l2 -notmatch '^\s*//'){break}
          $t=($l2 -replace '^\s*//\s?','').Trim(); if($t -eq '}'){break}
          if($t -match '^theory\s+[A-Za-z0-9_]+\s*\{'){break}; if($t -match '^[A-Za-z0-9_]+\s*:\s*.*->.*=\s*.*->'){break}; $body+=$t } }
      else { $depth=0;$st=$false
        for($j=$i;$j -lt $lines.Length;$j++){ $l2=$lines[$j]
          $o=([regex]::Matches($l2,'\{')).Count; $cl=([regex]::Matches($l2,'\}')).Count
          if($j -gt $i){$body+=$l2}
          $depth+=$o-$cl; if($o -gt 0){$st=$true}; if($st -and $depth -le 0){break} } }
      $decl=0;$hole=$false
      foreach($bl in $body){ $t=$bl.Trim()
        if($t -eq '' -or $t -eq '{' -or $t -eq '}'){continue}
        if($t -match '^//'){continue}
        if($t -match '\?\?\?'){$hole=$true}
        if($t -match '\bTODO\b'){$hole=$true; continue}
        if($t -match '^include\b'){ if($t -match '='){$decl++}; continue }
        if($t -match '^(type|realize)\b'){$decl++; continue}
        if($t -match '^[A-Za-z0-9_]+[^:=]*:' -or $t -match '^[A-Za-z0-9_]+[^:=]*='){$decl++} }
      $mmt = if($cnt.ContainsKey($name)){$cnt[$name]}else{-1}
      if($decl -eq 0){
        if($hole){ $part++ }
        elseif($mmt -eq 0){ $comp++ }
        else { $emp++ }
      } else {
        if($hole){ $part++ }
        elseif($mmt -gt 0 -and $decl -lt $mmt){ $part++ }
        else { $comp++ }
      }
    }
  }
  $rows += [pscustomobject]@{F=$f;C=$comp;P=$part;E=$emp;T=$tot}
}
$rows | ForEach-Object { Write-Output ("{0}|complete={1}|partial={2}|empty={3}|total={4}" -f $_.F,$_.C,$_.P,$_.E,$_.T) }
Write-Output ("TOTAL|complete={0}|partial={1}|empty={2}|total={3}" -f (($rows|Measure-Object -Property C -Sum).Sum),(($rows|Measure-Object -Property P -Sum).Sum),(($rows|Measure-Object -Property E -Sum).Sum),(($rows|Measure-Object -Property T -Sum).Sum))

